<script lang="ts">
 import type {Readable} from 'svelte/store';
 import TextNodes from './TextNodes.svelte';
 import MaterialContribution from './MaterialContribution.svelte';
 let {store,materials,controller:c,repair,overlays,t}=$props<{store:Readable<any>,materials:Readable<any>,controller:any,repair:any,overlays:any,t:any}>();
 let root=$state<HTMLDivElement>(),detail=$state<HTMLDivElement>();
 let open=$derived($store.open);
 const a=(action:string,value?:any,extra?:any,guard?:any)=>c.act(action,value,extra,guard);
 const tabs=['all','materials','equipment','perishable','locked','starred'];
 $effect(()=>{if(open&&root)return overlays.enter(root,{escape:c.close});});
 function project(id:string){a('project',id);if(detail)detail.scrollTop=0;}
</script>
<div id="modal-hideout-warehouse" class:show={$store.open} class:hw-project-view={$store.upgradeOpen} aria-hidden={!$store.open} data-ui-owner="svelte" bind:this={root}>
 {#if $store.open}
 {@const v=$store}{@const u=v.upgrade}{@const d=v.detail}
 <div class="hw-panel">
  <header class="hw-header"><div class="hw-header-left"><h2 class="hw-title">{t('hideout_warehouse.title')}</h2><span id="hw-badge-outpost" class="hw-badge hw-badge-outpost" class:hw-hidden={!v.outpost}>{t('hideout_warehouse.badge.outpost')}</span><span id="hw-badge-frost" class="hw-badge hw-badge-frost" class:hw-hidden={!v.cold}>{t('hideout_warehouse.badge.frost')}</span></div><div class="hw-header-right"><div class="hw-capacity"><span>{t('hideout_warehouse.capacity.prefix')}</span><span id="hw-capacity-num">{v.used} / {v.capacity}</span><span data-ui="hideout_warehouse.capacity.suffix">{t('hideout_warehouse.capacity.suffix')}</span></div><div class="hw-header-actions"><button type="button" class="hw-btn-secondary" class:hw-hidden={!v.qos.qol_craft_stash} class:hw-btn-active={v.qos.qol_craft_stash&&v.prefer} id="hw-btn-settings" title={t(v.qos.qol_craft_stash?(v.prefer?'hideout_warehouse.settings.prefer_warehouse_on':'hideout_warehouse.settings.prefer_warehouse_off'):'hideout_warehouse.btn.settings')} onclick={()=>a('settings')}>⚙</button><button type="button" class="hw-btn-secondary" class:hw-hidden={!v.qos.qol_tidy_one_click} id="hw-btn-tidy" onclick={()=>a('tidy')}>{t('hideout_warehouse.btn.tidy')}</button><button type="button" class="hw-close" id="hw-close" aria-label="关闭" aria-disabled="false" onclick={c.close}>✕</button></div></div></header>
  <nav class="hw-workspace-nav" aria-label="仓库页面"><button type="button" id="hw-btn-storage" class:active={!v.upgradeOpen} aria-pressed={!v.upgradeOpen} onclick={()=>a('storage')}>物品存取</button><button type="button" id="hw-btn-upgrade" class:active={v.upgradeOpen} aria-pressed={v.upgradeOpen} hidden={v.outpost} onclick={()=>a('upgrade')}>整备扩建</button><span>藏身处 · 仓库</span></nav>
  <div class="hw-body">
   <nav id="hw-tab-rail" class="hw-tab-rail" aria-label="筛选">{#each tabs as tab}<button type="button" class="hw-cat-btn" class:active={v.filter===tab&&(tab==='all'||v.qos.qol_tab_view)} class:hw-hidden={tab!=='all'&&!v.qos.qol_tab_view} data-tab={tab} onclick={()=>a('filter',tab)}>{t('hideout_warehouse.tab.'+tab)}</button>{/each}</nav>
   <div class="hw-grid-column"><div class="hw-grid-head"><h3 class="hw-hub-title">{t('hideout_warehouse.grid.section')}</h3><span id="hw-pager-info" class="hw-pager-info">{t('hideout_warehouse.pager.page_label',{page:v.page,totalPages:v.totalPages,pageSize:v.pageSize})}</span></div><div id="hw-slot-grid" aria-label="仓格网格">
