    {#if d}{#if v.pin}<div class="hw-detail-meta-row"><button type="button" class="hw-btn-secondary hw-btn-sm" id="hw-btn-star" onclick={()=>a('star',d.index,undefined,d.guard)}>{t(d.starred?'hideout_warehouse.btn.unstar':'hideout_warehouse.btn.star')}</button><button type="button" class="hw-btn-secondary hw-btn-sm" id="hw-btn-lock" onclick={()=>a('lock',d.index,undefined,d.guard)}>{t(d.locked?'hideout_warehouse.btn.unlock':'hideout_warehouse.btn.lock')}</button></div>{/if}{#if d.desc}<div><div class="hw-hub-title">{t('hideout_warehouse.detail.section.desc')}</div><p class="hw-detail-desc">{d.desc}</p></div>{/if}{#if d.modules.length}<div class="hw-detail-module"><div class="hw-hub-title">{t('hideout_warehouse.detail.section.spec')}</div><div class="bp-detail-modules"><TextNodes nodes={d.modules}/></div></div>{/if}<div class="hw-detail-actions"><button type="button" class="hw-btn-primary hw-btn-lg" id="hw-btn-withdraw-all" disabled={v.outpost||d.locked} onclick={()=>a('withdraw',d.index,null,d.guard)}>{t('hideout_warehouse.btn.withdraw_all')}</button><button type="button" class="hw-btn-secondary hw-btn-lg" id="hw-btn-withdraw-one" disabled={v.outpost||d.locked} onclick={()=>a('withdraw',d.index,1,d.guard)}>{t('hideout_warehouse.btn.withdraw_one')}</button>{#if v.qos.qol_withdraw_fill}<button type="button" class="hw-btn-secondary hw-btn-lg" id="hw-btn-withdraw-fill" disabled={v.outpost||d.locked} onclick={()=>a('fill',d.index,undefined,d.guard)}>{t('hideout_warehouse.btn.withdraw_fill')}</button>{/if}<div id="hw-withdraw-hint" class="hw-withdraw-hint" class:hw-hidden={!v.outpost}>{t('hideout_warehouse.hint.withdraw_blocked')}</div>{#if d.locked&&!v.outpost}<div class="hw-withdraw-hint">{t('hideout_warehouse.hint.slot_locked')}</div>{/if}</div>{/if}
   </aside>
   <div id="hw-upgrade-overlay" class:hw-hidden={!v.upgradeOpen} aria-hidden={!v.upgradeOpen}>
