    <div class="hw-upgrade-detail" bind:this={detail}><button type="button" class="hw-upgrade-close" id="hw-upgrade-close" aria-disabled="false" onclick={()=>a('storage')}>返回存取</button><div class="hw-hub-title">整备计划</div><div id="hw-project-stages" aria-label="工程阶段"></div><h3 class="hw-upgrade-detail-name" id="hw-upgrade-detail-name" hidden={u?.status==='materials'}>{u?.title||''}</h3><p class="hw-upgrade-detail-desc" id="hw-upgrade-detail-desc">{u?.desc||''}</p><div class="hw-upgrade-req-grid" id="hw-upgrade-req-grid" hidden={u?.status==='materials'}>{u?.stateText||''}{#if u?.costText}<p class="hw-work-cost">{u.costText}</p>{/if}</div><div id="hw-material-host" hidden={!u?.materials}>{#if $materials.open&&$materials.location==='warehouse'}<div class="facility-material-embedded" data-ui-owner="svelte"><MaterialContribution value={$materials} controller={repair}/></div>{/if}</div><div class="hw-progress-track hw-hidden" id="hw-upgrade-progress-track" aria-hidden="true"><div class="hw-progress-fill" id="hw-upgrade-progress-fill"></div></div><p role="status" class="hw-upgrade-progress-label" class:hw-hidden={!u||u.route} id="hw-upgrade-progress-label">{u?.message||''}</p><div class="hw-upgrade-foot"><div class="hw-upgrade-deduct" id="hw-upgrade-deduct">{u?.deduct||''}</div><button type="button" class="hw-btn-primary hw-btn-lg" class:hw-btn-disabled={!u?.route&&u?.disabled} id="hw-btn-upgrade-start" hidden={u?.status==='materials'} disabled={u?.disabled} onclick={()=>a('start')}>{u?.start||t('hideout_warehouse.upgrade.start')}</button></div></div>
   </div>
  </div>
  <div id="hw-container-strip" aria-label="人物容器">{#each v.containers as container,i}{#if i}<div class="hw-container-divider" aria-hidden="true"></div>{/if}<div class="hw-container-block" class:hw-container-flex={container.id==='backpack'} data-container={container.id}><div class="hw-container-head"><span class="hw-container-title">{t('hideout_warehouse.container.'+(container.id==='pocket'?'pockets':container.id))}</span><button type="button" class="hw-container-deposit" class:hw-hidden={!v.qos.qol_deposit_all} data-container={container.id} onclick={()=>a('depositAll',container.id)}>{t('hideout_warehouse.container.deposit_all')}</button></div><div class="hw-container-slots">{#each container.items as item(item.index)}<button type="button" class="hw-mini-slot" data-container={container.id} data-container-index={item.index} title={'存入：'+item.label} onclick={()=>a('deposit',container.id,item.index,item.guard)}>{item.label}</button>{:else}<div class="hw-mini-slot hw-mini-empty">{t('hideout_warehouse.slot.empty')}</div>{/each}</div></div>{/each}</div>
  <footer class="hw-footer"><p id="hw-footer-hint">{v.upgradeOpen?'已投入的材料与已完成的工程都会保留。':'点击下方随身物品存入；选择仓格后取出。'}</p><span class="hw-footer-sub">{t('hideout_warehouse.footer.death_hint')}</span></footer>
 </div>{/if}
</div>
